local HandCannonMaker = {}
local PRODUCTS = {
    simple_hand_cannon = { name = "Preprosta ročna topovska", ironCost = 2, woodCost = 2, gunpowderCost = 1, time = 3, cost = 80, attack = 25, range = 60, durability = 25, description = "Preprosta ročna topovska za pehoto." },
    matchlock_hand_cannon = { name = "Svečno prižigana ročna topovska", ironCost = 3, woodCost = 2, gunpowderCost = 1, time = 5, cost = 200, attack = 40, range = 80, durability = 35, prestige = 2, description = "Ročna topovska z učinkovitim prižigom." },
    wheellock_pistol = { name = "Kolesni pistoli", steelCost = 2, ironCost = 2, woodCost = 1, gunpowderCost = 1, time = 7, cost = 480, attack = 55, range = 100, durability = 45, prestige = 5, happiness = 1, description = "Kolesni pistoli za viteze." },
    silver_decorated_hand_cannon = { name = "Srebrno okrašena ročna topovska", steelCost = 2, ironCost = 2, silverCost = 1, woodCost = 2, gunpowderCost = 1, time = 9, cost = 950, attack = 75, range = 120, durability = 55, prestige = 10, happiness = 2, description = "Ročna topovska s srebrnim okrasjem za plemiče." },
    gold_inlaid_hand_cannon = { name = "Zlatorobna ročna topovska", steelCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, woodCost = 2, gunpowderCost = 2, time = 12, cost = 1900, attack = 100, range = 150, durability = 70, prestige = 18, happiness = 4, description = "Ročna topovska z zlatorobnim okovjem za visoke častnike." },
    royal_ceremonial_hand_cannon = { name = "Kraljevski slovesna ročna topovska", steelCost = 4, ironCost = 2, goldCost = 2, silverCost = 2, woodCost = 3, gunpowderCost = 2, jewelCost = 1, pearlCost = 1, time = 18, cost = 4200, attack = 150, range = 200, durability = 100, prestige = 45, happiness = 9, description = "Velika kraljevska slovesna ročna topovska z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ročnotopovska delavnica", cost = { gold = 320, wood = 130, stone = 150 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Ročnotopovska kovačija", cost = { gold = 1100, wood = 220, stone = 300, iron = 8 }, upkeep = 28, qualityBonus = 18 },
    lock_room = { name = "Prižigalnica", cost = { gold = 2500, wood = 280, stone = 500, silver = 40, steel = 8 }, upkeep = 60, qualityBonus = 30 },
    royal_handcannon_atelier = { name = "Kraljevski atelje ročnih topov", cost = { gold = 9000, wood = 500, stone = 800, gold = 100, jewel = 25 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 40 },
}
HandCannonMaker.ironStock = 14; HandCannonMaker.steelStock = 12; HandCannonMaker.woodStock = 14; HandCannonMaker.silverStock = 8; HandCannonMaker.goldStock = 6; HandCannonMaker.jewelStock = 6; HandCannonMaker.pearlStock = 4; HandCannonMaker.gunpowderStock = 12
HandCannonMaker.productStock = {}; HandCannonMaker.buildings = {}; HandCannonMaker.maker = nil; HandCannonMaker.activeMaking = {}; HandCannonMaker.totalProducts = 0; HandCannonMaker.dayTimer = 0
function HandCannonMaker.init() HandCannonMaker.ironStock=14; HandCannonMaker.steelStock=12; HandCannonMaker.woodStock=14; HandCannonMaker.silverStock=8; HandCannonMaker.goldStock=6; HandCannonMaker.jewelStock=6; HandCannonMaker.pearlStock=4; HandCannonMaker.gunpowderStock=12; HandCannonMaker.productStock={}; HandCannonMaker.buildings={}; HandCannonMaker.maker=nil; HandCannonMaker.activeMaking={}; HandCannonMaker.totalProducts=0; HandCannonMaker.dayTimer=0; print("[HandCannonMaker] Royal Hand Cannon Maker System initialized (6 products, 4 buildings)") end
function HandCannonMaker.hireMaker(n,s) s=s or math.random(55,95); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HandCannonMaker.maker={name=n or ("Ročnotopar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ročnotopar najet: %s (spretnost: %d)",HandCannonMaker.maker.name,s),"success") end; return true end
function HandCannonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HandCannonMaker.build(id) local ok,e=HandCannonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HandCannonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HandCannonMaker.getQualityBonus() local b=0; for _,bd in ipairs(HandCannonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HandCannonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HandCannonMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and HandCannonMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and HandCannonMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and HandCannonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HandCannonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HandCannonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HandCannonMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if d.gunpowderCost and HandCannonMaker.gunpowderStock<(d.gunpowderCost or 0) then return false,"Premalo smodnika" end; if #HandCannonMaker.buildings==0 then return false,"Potrebna delavnica" end; if not HandCannonMaker.maker then return false,"Potreben ročnotopar" end; return true end
function HandCannonMaker.make(pt,qty) qty=qty or 1; local ok,e=HandCannonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HandCannonMaker.ironStock=HandCannonMaker.ironStock-d.ironCost*qty end; if d.steelCost then HandCannonMaker.steelStock=HandCannonMaker.steelStock-d.steelCost*qty end; if d.woodCost then HandCannonMaker.woodStock=HandCannonMaker.woodStock-d.woodCost*qty end; if d.silverCost then HandCannonMaker.silverStock=HandCannonMaker.silverStock-d.silverCost*qty end; if d.goldCost then HandCannonMaker.goldStock=HandCannonMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HandCannonMaker.jewelStock=HandCannonMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HandCannonMaker.pearlStock=HandCannonMaker.pearlStock-d.pearlCost*qty end; if d.gunpowderCost then HandCannonMaker.gunpowderStock=HandCannonMaker.gunpowderStock-d.gunpowderCost*qty end; local t=d.time; if HandCannonMaker.maker then t=math.max(1,t-math.floor(HandCannonMaker.maker.skill/12)) end; table.insert(HandCannonMaker.activeMaking,{id="handcannon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HandCannonMaker.completeMaking(m) local q=1.0+(HandCannonMaker.getQualityBonus()/100); if HandCannonMaker.maker then q=q+(HandCannonMaker.maker.skill/150) end; q=math.min(2.5,q); HandCannonMaker.productStock[m.productType]=(HandCannonMaker.productStock[m.productType] or 0)+m.quantity; HandCannonMaker.totalProducts=HandCannonMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HandCannonMaker.maker then HandCannonMaker.maker.itemsMade=HandCannonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HandCannonMaker.maker.skill=math.min(100,HandCannonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ročna topovska izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"handcannon.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function HandCannonMaker.update(dt) if not _G.state then return end; HandCannonMaker.dayTimer=HandCannonMaker.dayTimer+dt; if HandCannonMaker.dayTimer>=30 then HandCannonMaker.dayTimer=0; for i=#HandCannonMaker.activeMaking,1,-1 do local m=HandCannonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HandCannonMaker.completeMaking(m); table.remove(HandCannonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HandCannonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HandCannonMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HandCannonMaker.getStats() return {ironStock=HandCannonMaker.ironStock,steelStock=HandCannonMaker.steelStock,woodStock=HandCannonMaker.woodStock,silverStock=HandCannonMaker.silverStock,goldStock=HandCannonMaker.goldStock,jewelStock=HandCannonMaker.jewelStock,pearlStock=HandCannonMaker.pearlStock,gunpowderStock=HandCannonMaker.gunpowderStock,productStock=HandCannonMaker.productStock,numBuildings=#HandCannonMaker.buildings,hasMaker=HandCannonMaker.maker~=nil,makerName=HandCannonMaker.maker and HandCannonMaker.maker.name or "—",makerSkill=HandCannonMaker.maker and HandCannonMaker.maker.skill or 0,activeMaking=#HandCannonMaker.activeMaking,totalProducts=HandCannonMaker.totalProducts} end
return HandCannonMaker
